import type { D1AuthoredBank } from '../corpus'

export const PESISIR_UTARA_D_R2: D1AuthoredBank = {
  universeId: 'pesisir-utara',
  rubricId: 'D-R2',
  STRONG: [
    { chapters: [
      { chapterNumber: 9, title: 'Menandatangani Nama Orang', paragraphs: ['Ketika berkas penerimaan garam harus disahkan, Sari menuliskan nama Bu Hasnah pada kolom penanggung jawab dan hanya membubuhkan paraf kecil miliknya di sudut. Pengurus gudang itu tidak menolak karena sudah terbiasa dipakai sebagai perisai. Petugas izin menerima berkas tanpa membaca. Sari pulang merasa aman sebab tidak ada satu pun kertas hari itu yang membawa namanya secara utuh.'] },
      { chapterNumber: 13, title: 'Cap Lilin Dipanaskan', paragraphs: ['Malam bongkaran ikan asin, Sari memanaskan cap lilin biru di atas nyala lampu minyak dan menekannya pada berkas yang lagi-lagi memuat nama pengurus gudang. Bu Hasnah menawarkan diri membaca angkanya, lalu Sari berkata tidak perlu. Lilin mengeras cepat di udara asin. Ia menyimpan kenyamanan itu seperti menyimpan uang receh di saku baju kerjanya.'] },
      { chapterNumber: 14, title: 'Pemeriksa Pusat Diumumkan', paragraphs: ['Pengumuman ditempel di papan dermaga: pemeriksa dari pusat akan menelusuri seluruh berkas garam musim ini. Kuli bongkar membacanya keras-keras sambil tertawa cemas. Sari menghitung berapa banyak lembar yang telah ia sahkan memakai nama orang lain, lalu berhenti pada hitungan keempat puluh. Ia melipat pengumuman itu dan memasukkannya ke laci paling bawah.'] },
      { chapterNumber: 15, title: 'Paraf Ditolak Petugas', paragraphs: ['Petugas loket mengembalikan berkas dan berkata paraf sudut tidak lagi diterima sejak pemeriksaan pusat datang. Sari menawarkan nama Pak Uweng, lalu juru timbang itu menggeleng pelan tanpa marah. Tangannya berkeringat memegang pena. Ia menunda pengesahan sampai sore, dan untuk pertama kalinya menyadari bahwa persembunyian itu selama ini dibayar oleh orang lain.'] },
      { chapterNumber: 16, title: 'Bertanya kepada Timbangan', paragraphs: ['Sari menemui Pak Uweng sebelum dermaga ramai dan meminta diajari cara pembacaan timbangan garam dicatat ulang bila jarumnya bergetar. Juru timbang itu menunjukkan dua angka berbeda untuk muatan yang sama. Sari menyalin keduanya ke telapak tangannya, lalu memindahkan angka tersebut ke halaman belakang buku muatan sebelum keringat menghapus tinta dari kulitnya.'] },
      { chapterNumber: 17, title: 'Tawaran di Ruang Belakang', paragraphs: ['Regent Damar memanggilnya ke ruang belakang kantor izin dan menawarkan meja tetap dengan upah dua kali lipat asalkan berkas musim ini tetap disahkan seperti biasa. Sari memandang cangkir yang disodorkan tanpa menyentuhnya. Ia menjawab akan memikirkannya sampai pekan depan. Di luar, angin membawa bau lumpur pasang. Surat tawaran itu tetap terlipat di tangannya sampai ia tiba di dermaga.'] },
      { chapterNumber: 18, title: 'Hasnah Dipanggil Kantor', paragraphs: ['Bu Hasnah dipanggil menghadap dengan membawa seluruh berkas gudang yang memuat namanya. Sari menunggu di luar sambil memegang payung yang tidak dipakai. Perempuan itu keluar dua jam kemudian dan berkata ia diminta menjelaskan angka yang tidak pernah ia hitung. Sari membawakan payungnya, lalu berjalan pulang tanpa berani menyebut siapa yang menulis angka tersebut.'] },
      { chapterNumber: 19, title: 'Menyalin Ulang Semalaman', paragraphs: ['Sari menyalakan lampu minyak dan menyalin ulang berkas garam tiga musim terakhir memakai angka timbangan yang benar. Tangannya kram menjelang subuh dan kertasnya berbau lilin. Ia menuliskan namanya sendiri pada setiap lembar salinan, meski belum menyerahkannya kepada siapa pun. Berkas salinan dibundel memakai tali bekas, kemudian dimasukkan ke dalam tas kerjanya.'] },
      { chapterNumber: 20, title: 'Ancaman Giliran Kerja', paragraphs: ['Petugas loket memberitahunya bahwa juru catat yang membuat kantor repot biasanya kehilangan giliran kerja sampai musim berganti. Sari bertanya apakah itu peraturan atau kebiasaan, dan lelaki itu tidak menjawab. Ia kembali ke mejanya, menghitung sisa beras di rumah, lalu memeriksa kembali ikatan tali pada salinan yang ia bawa sejak pagi.'] },
      { chapterNumber: 22, title: 'Nama Sendiri di Kolom', paragraphs: ['Sari menuliskan namanya sendiri pada kolom penanggung jawab berkas garam yang jumlahnya ia ubah sesuai timbangan sebenarnya. Regent Damar membaca lembar itu di hadapannya lalu menyebut jabatan juru catat mudah diganti. Sari tidak menarik pena. Ia kehilangan giliran kerja pekan berikutnya, tetapi berkas yang beredar kini memuat angka yang dapat ia pertahankan sendiri.'] },
    ], justification: 'Bab 9 shows Sari signing under Bu Hasnah’s name; Bab 22 has her put her own name on a corrected manifest and lose her work rotation for it.' },
    { chapters: [
      { chapterNumber: 9, title: 'Menyuruh Latif Diam', paragraphs: ['Latif hendak menyebutkan awak tanpa karcis kepada juru mudi, lalu Sari menariknya ke belakang tumpukan tali dan menyuruhnya menutup mulut. Ia berkata keluarga mereka hanya memiliki satu pekerjaan tetap di pelabuhan ini. Adiknya menurut sambil menunduk. Sari merasa telah melindungi mereka berdua dengan cara yang paling murah.'] },
      { chapterNumber: 13, title: 'Anak Geladak Bertanya', paragraphs: ['Seorang awak muda mendekati Latif di ujung dermaga dan menanyakan kepada siapa upah pelayaran ketiga harus ditagih. Sari menjawab lebih dulu bahwa urusan upah bukan wilayah keluarga mereka, lalu menarik adiknya menjauh dari tangga kapal. Anak itu berdiri sendirian memegang topi. Camar berputar rendah, dan Sari memilih tidak menoleh ke belakang.'] },
      { chapterNumber: 14, title: 'Daftar Awak Ditempel', paragraphs: ['Kantor izin menempel daftar awak resmi di dinding pos jaga, dan enam nama yang biasa terlihat memanggul karung tidak tercantum di sana. Kuli bongkar berdesakan membaca sambil menghitung dengan jari. Sari mengenali dua wajah di antara nama yang hilang itu. Ia menyalin daftar tersebut ke buku kecilnya lalu menutupnya sebelum ada yang menegur.'] },
      { chapterNumber: 15, title: 'Diam yang Menghukum', paragraphs: ['Seorang awak muda dipulangkan tanpa upah karena dianggap tidak tercatat, dan Latif berdiri di dermaga tanpa berkata apa-apa sesuai perintah kakaknya. Sari melihat wajah adiknya dari jendela kantor. Malamnya mereka makan tanpa bicara. Ia mulai mengerti bahwa diam yang ia ajarkan telah berubah menjadi beban yang dipikul adiknya sendirian.'] },
      { chapterNumber: 16, title: 'Latif Bertanya Ulang', paragraphs: ['Di dapur rumah petak mereka, Latif menanyakan mengapa awak yang dipulangkan tidak pernah muncul lagi di dermaga. Sari menjawab bahwa orang datang dan pergi di pelabuhan mana pun. Adiknya menaruh sendok lalu berkata ia sudah lelah menghafal alasan itu. Untuk pertama kalinya Sari kehabisan kalimat yang biasanya cukup untuk menutup percakapan.'] },
      { chapterNumber: 17, title: 'Nyi Ratih Memberi Nama', paragraphs: ['Di warung yang hampir tutup, Nyi Ratih mengungkap identitas awak muda beserta kampung asalnya, kemudian bercerita bahwa sang ibu sempat mencari kabar di pos jaga. Sari mendengarkan sambil memutar gelas kopinya. Nama tersebut kini tidak bisa lagi dianggap sekadar wajah asing. Nama tersebut dicatatnya pada lembar tersembunyi di catatan muatan sebelum pulang.'] },
      { chapterNumber: 18, title: 'Latif Dipindah Malam', paragraphs: ['Jadwal feri diubah dan Latif dipindahkan ke pelayaran malam yang paling jarang diawasi. Ia pulang menjelang subuh dengan tangan pecah-pecah oleh air asin. Sari menyadari bahwa perlindungan yang ia banggakan tidak pernah benar-benar melindungi siapa pun. Ia duduk menunggu adiknya sampai lampu suar padam, tanpa mengatakan apa yang ia rencanakan.'] },
      { chapterNumber: 19, title: 'Menghitung Hari Kerja', paragraphs: ['Sari mencocokkan karcis feri, buku muatan, dan daftar pos jaga sampai memperoleh jumlah hari kerja awak muda itu. Angkanya keluar dua puluh tiga hari tanpa satu pun catatan upah. Ia menyalinnya rapi di kertas terpisah. Lembar tersebut dilipat menjadi kotak kecil, kemudian diselipkan ke saku dalam bajunya alih-alih laci meja kantor.'] },
      { chapterNumber: 20, title: 'Peringatan di Pos Jaga', paragraphs: ['Petugas pos jaga memanggilnya sebentar dan berkata orang yang menyebut nama di depan loket biasanya membuat keluarganya kehilangan izin masuk dermaga. Sari bertanya izin siapa yang dimaksud, dan lelaki itu hanya menyebut kata adik. Ia berjalan pulang melewati tumpukan tali temali, memegang saku bajunya sepanjang jalan.'] },
      { chapterNumber: 22, title: 'Bicara di Depan Loket', paragraphs: ['Di depan loket yang penuh, Sari menyebutkan nama awak muda itu dan meminta upahnya dibayarkan sesuai hari kerja. Petugas mengancam mencabut izin masuk dermaga bagi Latif. Sari tetap berdiri dan mengulang nama tersebut sampai dicatat. Adiknya kehilangan giliran feri selama sebulan, sementara upah yang tertahan akhirnya keluar dari kas pelabuhan.'] },
    ], justification: 'Sari’s established rule of silence in Bab 9 is broken in Bab 22 by naming a worker publicly, at the direct price of Latif’s ferry rotation.' },
    { chapters: [
      { chapterNumber: 9, title: 'Buku Kedua Disembunyikan', paragraphs: ['Sari menyimpan buku muatan kedua di bawah papan lantai kamarnya dan tidak menunjukkannya kepada siapa pun, bahkan kepada Bu Hasnah yang menanyakan angka bongkaran. Ia menganggap catatan itu jaminan pribadi bila suatu hari dituduh lalai. Debu menutup sela papan setiap malam. Pengetahuannya menjadi milik satu orang, dan hal itu terasa aman baginya.'] },
      { chapterNumber: 13, title: 'Uweng Menanyakan Salinan', paragraphs: ['Pak Uweng bertanya apakah ada salinan lain dari bongkaran musim lalu karena angka gudang tidak cocok dengan catatan pos jaga. Sari menggeleng sambil merapikan tumpukan karcis feri. Juru timbang itu tidak mendesak, hanya menatap laci mejanya sebentar lalu pamit. Sore harinya Sari pulang lebih awal dan memeriksa paku papan lantai kamarnya satu per satu.'] },
      { chapterNumber: 14, title: 'Gudang Diukur Ulang', paragraphs: ['Tim pemeriksa mengukur isi gudang garam selama dua hari penuh dan menemukan selisih yang tidak dapat dijelaskan oleh siapa pun di dermaga. Bu Hasnah menandatangani berita acara sebab namanya tertera sebagai penanggung jawab ruang. Sari berdiri dekat pintu memegang pensil tanpa menulis apa pun. Debu garam menempel di lengan bajunya sampai malam.'] },
      { chapterNumber: 15, title: 'Hasnah Dituduh Lalai', paragraphs: ['Kantor izin menuduh Bu Hasnah salah menghitung kiriman dan menahan upah gudang selama dua pekan. Sari tahu angka sebenarnya tersimpan di kolong lantai kamarnya, namun ia hanya membawakan makan siang. Pengurus gudang itu berterima kasih dengan suara serak. Rasa aman yang dijaga Sari mulai terasa seperti sesuatu yang ia curi dari orang lain.'] },
      { chapterNumber: 16, title: 'Upah Gudang Ditahan', paragraphs: ['Kas pelabuhan menahan upah seluruh pekerja gudang sampai selisih itu dijelaskan. Bu Hasnah tetap datang setiap pagi dan membuka pintu besi seperti biasa, hanya makan siangnya berhenti. Sari membawakan nasi bungkus tanpa mengatakan alasannya. Perempuan itu menerima sambil berterima kasih, dan rasa terima kasih tersebut terasa lebih berat daripada tuduhan mana pun.'] },
      { chapterNumber: 17, title: 'Damar Menawarkan Kepastian', paragraphs: ['Regent Damar memanggil Sari dan berkata perkara gudang akan ditutup bila juru catat menyatakan penghitungan pengurus memang serampangan. Sebagai gantinya, meja Sari dijamin aman sampai musim kering berakhir. Sari menanyakan siapa yang menandatangani pernyataan itu. Lelaki itu menjawab cukup satu nama saja, lalu mendorong lembar kosong ke arahnya.'] },
      { chapterNumber: 18, title: 'Lembar Kosong Dibawa Pulang', paragraphs: ['Sari membawa lembar pernyataan kosong itu pulang dan meletakkannya di meja dekat lampu minyak. Ia membaca kalimat pembukanya berulang kali sampai minyak hampir habis. Di bawah papan lantai, buku muatan keduanya tetap diam seperti selalu. Ia tidak menandatangani apa pun malam itu, tetapi juga tidak membakar lembar tersebut.'] },
      { chapterNumber: 19, title: 'Angka Dicocokkan Lagi', paragraphs: ['Selama tiga malam Sari mencocokkan isi buku pribadinya dengan berita acara gudang dan menemukan bahwa selisihnya persis sama dengan muatan yang dinaikkan kembali ke kapal tanpa dicatat. Ia menandai halaman itu dengan benang merah, lalu meletakkannya berdampingan dengan berita acara yang memuat nama Bu Hasnah. Kedua angka yang sama dilingkarinya memakai tinta hitam.'] },
      { chapterNumber: 20, title: 'Hasnah Menolak Dibela', paragraphs: ['Bu Hasnah berkata ia tidak ingin ada orang muda kehilangan pekerjaan demi namanya yang sudah tua. Sari mendengarkan sambil menahan buku di dalam tas. Perempuan itu menepuk lengannya lalu kembali menyapu lantai gudang. Penolakan yang lembut itu justru membuat Sari mengerti bahwa keputusan tersebut tidak boleh ia serahkan kepada siapa pun.'] },
      { chapterNumber: 22, title: 'Buku Diserahkan Terbuka', paragraphs: ['Sari membawa buku muatan kedua ke ruang pemeriksaan dan meletakkannya di meja dengan sampul terbuka. Ia menjelaskan setiap halaman meski tahu catatan itu memperlihatkan ia telah menyimpan bukti selama berbulan-bulan. Pemeriksa mencatat kelalaiannya sekaligus membebaskan Bu Hasnah. Sari menerima teguran tertulis pertama dalam hidupnya tanpa membela diri.'] },
    ], justification: 'The private ledger hoarded in Bab 9 is surrendered in Bab 22 in a way that clears Bu Hasnah and earns Sari a formal reprimand.' },
    { chapters: [
      { chapterNumber: 9, title: 'Menghindari Warung Dermaga', paragraphs: ['Sari selalu melewati warung Nyi Ratih dari sisi jalan seberang karena tidak ingin terlihat berbicara dengan orang yang dianggap banyak mulut oleh kantor izin. Ia membeli makan di kios dekat gerbang saja. Kebiasaan itu membuat namanya bersih di mata pengawas. Ia menganggap jarak tersebut sebagai bentuk kehati-hatian yang wajar.'] },
      { chapterNumber: 13, title: 'Surat Teguran Ditempel', paragraphs: ['Selembar surat teguran ditempel di tiang warung dermaga, menyebut keramaian yang mengganggu lalu lintas bongkar muat. Nyi Ratih membacanya sambil mengangkat kursi ke dalam. Sari melihat dari seberang jalan lalu meneruskan langkah ke kios gerbang. Ia memesan nasi seperti biasa, membayar, lalu pergi tanpa bertanya kepada penjual kios.'] },
      { chapterNumber: 14, title: 'Kuli Kehilangan Tempat', paragraphs: ['Sejak kursi warung diangkut ke dalam, kuli bongkar makan berdiri di bawah derek dengan piring di tangan. Hujan sore membuat nasi mereka bercampur air. Sari menghitung sembilan orang berdiri di tempat yang tidak seharusnya dipakai makan. Jumlah sembilan ditulisnya pada tepi halaman muatan, lalu buku segera ditutup.'] },
      { chapterNumber: 15, title: 'Ratih Kehilangan Izin', paragraphs: ['Kantor mencabut izin warung Nyi Ratih dengan alasan mengganggu ketertiban dermaga. Sari melihat kursi-kursi diangkut sementara ia berdiri di seberang jalan seperti biasanya. Perempuan tua itu tidak menyapanya. Malam itu Sari menyadari bahwa jaraknya bukan kehati-hatian, melainkan cara membiarkan orang lain berdiri sendirian.'] },
      { chapterNumber: 16, title: 'Warung Tanpa Pelanggan', paragraphs: ['Nyi Ratih tetap membuka pintu warungnya walau tidak seorang pun berani duduk di dalam. Air rebusan mendidih sampai kering di atas tungku. Sari lewat dua kali hari itu dan pada kali kedua melambatkan langkahnya. Perempuan tua itu menyapa tanpa mengharapkan jawaban, lalu kembali mengelap meja yang sudah bersih.'] },
      { chapterNumber: 17, title: 'Pengawas Menyebut Daftar', paragraphs: ['Seorang pengawas menyebutkan di depan Sari bahwa kantor menyimpan daftar pegawai yang perlu diperhatikan, dan nama juru catat yang bersih selalu berguna ketika musim izin tiba. Sari mengangguk sopan sambil membetulkan tumpukan berkas. Kalimat itu terdengar seperti pujian, tetapi ia mengenali bentuk peringatan di dalamnya.'] },
      { chapterNumber: 18, title: 'Kursi Ditawarkan Kembali', paragraphs: ['Nyi Ratih mengeluarkan satu kursi ke depan warung dan mengatakan siapa pun boleh memakainya. Kursi itu kosong sepanjang siang. Sari berdiri di seberang memegang berkas basah oleh gerimis, lalu menyeberang setengah jalan sebelum berbalik lagi. Malamnya ia tidak bisa tidur oleh bunyi kursi kayu yang diseret masuk.'] },
      { chapterNumber: 19, title: 'Keterangan Ditulis Malam', paragraphs: ['Sari mencatat bahwa sejak lima musim lalu para kuli bongkar menyantap makan malam di warung dermaga, lengkap dengan jumlah orang yang pernah ia hitung. Ia menyalinnya dua kali agar ada cadangan. Tulisan itu belum ditandatangani. Ia menyimpannya di antara lembar buku muatan yang selalu ia bawa ke kantor.'] },
      { chapterNumber: 20, title: 'Tanggal Pemeriksaan Ditetapkan', paragraphs: ['Kantor mengumumkan tanggal pemeriksaan izin warung, dan pengawas mengingatkan bahwa saksi akan dicatat namanya. Sari melihat papan pengumuman itu bersama kuli bongkar yang berdiri di belakangnya. Tidak ada yang bersedia menyebutkan diri. Ia pulang menghitung berapa lama namanya sudah bersih, lalu menyadari kebersihan itu tidak pernah ia bayar sendiri.'] },
      { chapterNumber: 22, title: 'Duduk di Kursi Terakhir', paragraphs: ['Sari duduk di kursi terakhir warung Nyi Ratih pada hari pemeriksaan izin dan menuliskan keterangan bahwa warung itu dipakai kuli bongkar untuk makan malam. Ia menandatanganinya di hadapan petugas. Namanya masuk ke daftar orang yang harus diawasi. Warung tetap buka dua bulan lagi, dan Sari berhenti berjalan di sisi seberang.'] },
    ], justification: 'Bab 9 establishes Sari avoiding Nyi Ratih to stay unmarked; Bab 22 has her testify publicly and be placed on a watch list.' },
    { chapters: [
      { chapterNumber: 9, title: 'Mengembalikan Peti Utuh', paragraphs: ['Ketika peti ikan asin datang dengan cap yang meragukan, Sari mengembalikannya utuh ke kapal dan menuliskan penolakan sederhana tanpa menyebut alasan sebenarnya. Ia belajar bahwa masalah yang dikirim kembali tidak akan menjadi berkas. Kuli bongkar memuji kecepatannya. Cara itu menjaga mejanya tetap rapi selama bertahun-tahun.'] },
      { chapterNumber: 13, title: 'Cap Lilin Retak', paragraphs: ['Segel biru pada muatan ikan asin pecah tepat di bagian tengah. Sari menahan kuli sebelum mereka menurunkan peti, lalu menulis satu baris penolakan tanpa mencatat kerusakan cap. Kapal berangkat menjelang senja sambil membawa muatan itu kembali. Meja Sari kembali kosong, sehingga ia tidak perlu memberi penjelasan kepada siapa pun.'] },
      { chapterNumber: 14, title: 'Pemuat Baru Diterima', paragraphs: ['Seorang petugas baru ditempatkan di jalur ikan asin dan menerima seluruh muatan yang datang tanpa membaca capnya. Kuli bongkar memuji kerjanya yang cepat. Sari memperhatikan bahwa jalur itu kini tidak lagi melewati mejanya sama sekali. Ia merasa lega selama satu hari penuh, sampai malamnya ia mulai menghitung peti yang lolos.'] },
      { chapterNumber: 15, title: 'Peti Kembali Bercap Sama', paragraphs: ['Peti yang sama muncul lagi dengan cap yang sudah diperbaiki dan diterima oleh petugas lain tanpa pertanyaan. Sari melihat nomor lambungnya cocok dengan yang pernah ia tolak. Ia menyimpan penolakan lamanya di laci. Mengembalikan peti ternyata hanya memindahkan persoalan ke tangan orang yang lebih mudah ditekan.'] },
      { chapterNumber: 16, title: 'Petugas Muda Ditegur', paragraphs: ['Petugas baru itu ditegur karena satu peti bocor mengotori lantai gudang, dan upah pekannya dipotong. Ia bertanya kepada Sari bagaimana cara mengenali muatan yang bermasalah. Sari menunjukkan letak retakan cap, lalu menyuruhnya mengembalikan peti serupa tanpa menulis alasan kerusakan pada lembar penolakan. Anak muda itu menyalin susunan kalimat pendek yang biasa dipakai Sari.'] },
      { chapterNumber: 17, title: 'Nomor Lambung Dicatat', paragraphs: ['Sari menyalin nomor lambung setiap kapal yang membawa peti bercap ganda selama dua pekan. Daftarnya mencapai lima baris, semuanya kembali ke satu pemilik yang sama. Kertas tersebut diselipkannya di balik sampul catatan bongkar. Baru kali ini ia mengumpulkan sesuatu yang tidak dapat diselesaikan dengan menaikkan peti kembali ke geladak.'] },
      { chapterNumber: 18, title: 'Kunci Gudang Diserahkan', paragraphs: ['Kepala gudang menyerahkan kunci ruang penyimpanan kepada Sari karena juru catat dianggap paling jarang membuat perkara. Ia menerima kunci itu dan menggantungnya di tali pinggangnya. Beratnya terasa asing sepanjang hari. Sejak sore itu, setiap peti yang masuk gudang menjadi tanggung jawab yang tidak bisa ia kirim pergi bersama kapal.'] },
      { chapterNumber: 19, title: 'Ancaman Melalui Kuli', paragraphs: ['Seorang kuli menyampaikan pesan dari kantor bahwa juru catat yang menahan muatan biasanya kehilangan wewenang tanda tangan sampai musim berikutnya. Sari bertanya siapa yang menitipkan pesan itu, dan lelaki tersebut hanya menunduk. Ia melanjutkan pekerjaannya sampai malam, lalu memeriksa persediaan tali rafia di sudut gudang.'] },
      { chapterNumber: 20, title: 'Kapal Bercap Ganda Datang', paragraphs: ['Kapal dengan nomor lambung yang lima kali ia catat merapat menjelang pasang naik, membawa peti yang capnya diperbaiki dengan lilin baru. Kuli bongkar menunggu perintah di bawah derek. Sari memegang kunci gudang di tangan kirinya dan daftar nomor lambung di tangan kanan. Tidak ada seorang pun yang menyuruhnya memilih.'] },
      { chapterNumber: 22, title: 'Menahan Peti di Gudang', paragraphs: ['Sari menahan peti bercap ganda di gudang, menyegelnya dengan tali rafia, lalu menulis laporan yang menyebut nomor lambung dan tanggal penolakan lamanya. Orang kantor datang menuntut peti dilepaskan malam itu juga. Ia menolak menyerahkan kunci gudang. Segel bertahan sampai pemeriksa datang, sementara Sari dipindahkan ke meja tanpa wewenang tanda tangan.'] },
    ], justification: 'Her long habit of quietly returning suspicious crates is replaced in Bab 22 by sealing one and filing a named report, costing her signing authority.' },
  ],
  WEAK: [
    { chapters: [
      { chapterNumber: 9, title: 'Paraf Kecil di Sudut', paragraphs: ['Sari membubuhkan paraf kecil di sudut berkas dan menyerahkan kolom penanggung jawab kepada nama Bu Hasnah. Petugas menerima tanpa memeriksa. Ia berkata kepada dirinya sendiri bahwa cara itu hanya berlaku sampai keadaan membaik. Berkas hari itu berjalan lancar dan tidak seorang pun menanyakan siapa yang sebenarnya menghitung.'] },
      { chapterNumber: 13, title: 'Tinta Baru Dibeli', paragraphs: ['Saat Bu Hasnah meminta Sari menggantikannya menerima muatan pagi, Sari mengatakan lututnya sakit dan memilih duduk di ruang belakang. Dari balik kisi ia menghitung karung yang lewat, tetapi setiap pertanyaan petugas diarahkan kepada pengurus gudang. Menjelang siang Sari berjalan pulang tanpa pincang. Nama Bu Hasnah tetap disebut pada seluruh urusan penerimaan hari itu.'] },
      { chapterNumber: 14, title: 'Petugas Menanyakan Penulis', paragraphs: ['Seorang petugas mendatangi meja timbang dan meminta orang yang menghitung muatan garam menunjukkan diri. Sari berdiri di antara kuli sambil membawa baki gelas, lalu berkata juru catat sedang mengambil makan. Setelah petugas pergi, baki kosong dikembalikan ke warung. Bu Hasnah dipanggil dari gudang untuk menjawab pertanyaan yang tidak pernah ia dengar sebelumnya.'] },
      { chapterNumber: 15, title: 'Berjanji Akan Berubah', paragraphs: ['Ketika Bu Hasnah ditegur karena angka yang tidak cocok, Sari berjanji ia akan memakai namanya sendiri mulai kiriman berikutnya. Ia mengucapkannya dua kali agar terdengar sungguh-sungguh. Sore itu berkas baru datang, dan kolom penanggung jawab kembali diisi nama pengurus gudang. Janji tersebut berhenti sebagai kalimat di ruang penyimpanan.'] },
      { chapterNumber: 16, title: 'Berlatih di Kertas Bekas', paragraphs: ['Sari mengusulkan agar petugas menanyakan angka melalui jendela belakang, tempat wajahnya tertutup rak karcis. Pak Uweng memindahkan satu bangku ke sana sebelum loket buka. Ketika pertanyaan pertama datang, Sari membisikkan jawabannya kepada Bu Hasnah untuk diteruskan. Menjelang petang bangku dikembalikan, sementara petugas tetap mengira pengurus gudang yang menghitung seluruh muatan.'] },
      { chapterNumber: 17, title: 'Hasnah Menawarkan Berhenti', paragraphs: ['Bu Hasnah menolak meneruskan jawaban Sari dan menyuruhnya berbicara langsung dari balik rak. Sari meminta waktu sampai bongkaran berikutnya, lalu memindahkan tumpukan karcis agar tubuhnya makin tertutup. Ketika petugas datang, ia kembali membisikkan angka melalui celah kayu. Bu Hasnah mengulangnya dengan suara keras tanpa menyebut siapa yang berada di belakangnya.'] },
      { chapterNumber: 18, title: 'Pemeriksa Menyusun Jadwal', paragraphs: ['Kantor memindahkan pemeriksaan ke ruang terbuka dekat timbangan. Sari datang membawa daftar angka, tetapi menyerahkannya kepada Pak Uweng sebelum petugas tiba. Sepanjang pemeriksaan ia berdiri di belakang tumpukan karung dan memberi isyarat dengan jari ketika juru timbang ragu. Semua pertanyaan selesai tanpa petugas memanggil namanya atau melihat daftar di tangannya.'] },
      { chapterNumber: 19, title: 'Uweng Menawarkan Saksi', paragraphs: ['Pak Uweng mengembalikan daftar itu dan berkata ia tidak akan menjawab lagi pada pemeriksaan berikutnya. Sari menawarkan menggantikan satu giliran timbang sebagai balasan, tetapi lelaki itu menolak. Keesokan pagi Sari menitipkan angka kepada kuli bongkar termuda. Ketika petugas bertanya, anak itu membacakannya sementara Sari mencatat dari ruang belakang.'] },
      { chapterNumber: 20, title: 'Malam Sebelum Pemeriksaan', paragraphs: ['Sebelum pemeriksaan terakhir, Sari menyusun meja agar rak karcis menutup pandangan dari pintu. Bu Hasnah menolak duduk di depannya, dan Pak Uweng bekerja di bak timbang. Sari meminta seorang kuli meninggalkan baki kosong dekat jendela sebagai alasan berada di belakang. Pagi berikutnya ia menunggu di sana, siap membisikkan angka kepada siapa pun yang lewat.'] },
      { chapterNumber: 22, title: 'Kolom Diisi Nama Lama', paragraphs: ['Pemeriksaan pusat berlangsung, lalu Sari menyalin lagi nama pengurus gudang ke baris tanggung jawab dengan alasan tulisan mereka mirip. Ia menepuk bahu perempuan itu setelah berkas diserahkan. Tidak ada risiko yang berpindah ke pundaknya. Kebiasaan yang ia janjikan akan ditinggalkan tetap berjalan persis seperti pada bongkaran pertama.'] },
    ], justification: 'Sari announces change in Bab 15 but Bab 22 repeats the exact avoidance from Bab 9 with no cost taken on.' },
    { chapters: [
      { chapterNumber: 9, title: 'Menyuruh Adik Menunduk', paragraphs: ['Sari menyuruh Latif menunduk dan tidak menyebut apa pun tentang awak tanpa karcis. Ia berkata pekerjaan mereka lebih penting daripada rasa ingin tahu. Adiknya menurut lalu kembali menggulung tali. Malam itu keduanya makan tanpa membicarakan siapa yang naik ke kapal garam sore tadi.'] },
      { chapterNumber: 13, title: 'Karcis Feri Dihitung', paragraphs: ['Latif menghitung karcis feri sore dan menemukan tiga penumpang lebih banyak daripada lembar yang terjual. Ia menunjukkan tumpukan itu kepada kakaknya di ruang tunggu. Sari mengambil karcis tersebut, merapikannya, lalu berkata angka begitu biasa terjadi bila cuaca ramai. Adiknya menerima penjelasan itu dan kembali menggulung tali sandar.'] },
      { chapterNumber: 14, title: 'Juru Mudi Berganti', paragraphs: ['Juru mudi lama dipindahkan ke jalur lain tanpa pengumuman, dan penggantinya tidak mengenal seorang pun di dermaga. Latif bercerita bahwa awak tanpa karcis kini naik lewat tangga belakang. Sari mendengarkan sambil membetulkan kerah baju adiknya. Ia meminta adiknya cukup menyelesaikan giliran masing-masing sampai musim berganti.'] },
      { chapterNumber: 15, title: 'Mengaku Ingin Bersuara', paragraphs: ['Sari mengatakan kepada Latif bahwa ia mulai merasa diam mereka keliru dan ingin membicarakannya kepada juru timbang. Latif menawarkan ikut menemani. Keesokan harinya juru timbang menyapa di dermaga, lalu Sari hanya menanyakan cuaca dan jadwal kapal. Keinginan bersuara tersebut tetap tertahan di kerongkongannya.'] },
      { chapterNumber: 16, title: 'Rapat Kecil di Pos', paragraphs: ['Beberapa kru feri berkumpul di pos jaga membicarakan giliran yang tidak pernah dibayar penuh. Latif mengajak kakaknya ikut mendengarkan. Sari berdiri dekat kusen pintu selama beberapa menit lalu pamit karena berkas gudang belum selesai. Pembicaraan itu berlanjut tanpa dirinya, dan tidak ada nama yang sempat ia dengar sampai habis.'] },
      { chapterNumber: 17, title: 'Nama Tertulis di Papan', paragraphs: ['Papan pos jaga memuat nama kru yang kehilangan giliran bulan ini, dan satu di antaranya adalah anak muda yang pernah dilarang Latif ditanyai. Sari membacanya sekilas saat lewat. Ia menyalin nama itu ke ingatan, bukan ke kertas. Malamnya ia berkata kepada adiknya bahwa daftar semacam itu selalu berganti sendiri.'] },
      { chapterNumber: 18, title: 'Latif Ditawari Pindah', paragraphs: ['Seorang petugas menawarkan Latif jalur feri pagi yang lebih tenang asalkan keluarganya tidak menanyakan urusan pencatatan awak. Latif menceritakannya di dapur sambil mengaduk teh. Sari menyebut tawaran itu rezeki dan menyuruhnya menerima. Adiknya menurut tanpa membantah, lalu keduanya melanjutkan makan dalam suasana yang sudah lama mereka kenali.'] },
      { chapterNumber: 19, title: 'Ratih Menanyakan Kabar', paragraphs: ['Nyi Ratih menghentikan Sari di dekat kios gerbang dan bertanya apakah benar ada kru yang tidak pernah pulang sejak pelayaran garam. Sari menjawab ia hanya mencatat muatan, bukan orang. Perempuan itu membalas dengan anggukan sebelum berjalan menuju warungnya. Sepanjang jalan pulang, Sari mengulang jawabannya sendiri seolah sedang menghafalkan sesuatu.'] },
      { chapterNumber: 20, title: 'Loket Menerima Pengaduan', paragraphs: ['Kantor membuka loket khusus pengaduan upah selama tiga hari, dan antreannya pendek karena hampir tidak ada yang berani. Latif berdiri jauh dari barisan sambil menunggu kakaknya. Sari lewat membawa berkas dan tidak menoleh ke loket itu. Ketiga hari tersebut habis, dan ia menyelesaikan seluruh pekerjaannya tanpa terlambat sekali pun.'] },
      { chapterNumber: 22, title: 'Menutup Mulut Adik Lagi', paragraphs: ['Ketika Latif hampir menyebut nama awak yang hilang di depan petugas, Sari menariknya menjauh dengan kalimat yang sama seperti dahulu. Ia mengingatkan bahwa mereka hanya punya satu pekerjaan tetap. Latif diam lalu pergi ke feri. Rumah mereka kembali sunyi tanpa satu pun risiko yang berani mereka ambil.'] },
    ], justification: 'The silence rule is verbally questioned in Bab 15 but re-imposed word-for-word in Bab 22, so no habit is actually broken.' },
    { chapters: [
      { chapterNumber: 9, title: 'Catatan Disimpan Sendiri', paragraphs: ['Sari menyalin angka bongkaran ke buku pribadi lalu menyelipkannya pada kolong lantai kamar. Bu Hasnah menanyakan apakah ada catatan tambahan, lalu Sari menjawab tidak ada. Ia merasa lebih tenang dengan pengetahuan yang tidak dibagi. Papan lantai ditutup kembali sebelum lampu kamar dimatikan.'] },
      { chapterNumber: 13, title: 'Paku Papan Diganti', paragraphs: ['Sari mengganti paku papan lantai kamarnya dengan yang lebih panjang supaya sela penyimpanan tidak mudah terbuka. Ia menekan papan itu berkali-kali sampai yakin tidak berbunyi. Buku pribadinya kini lebih rapat tersembunyi daripada sebelumnya. Malam itu ia tidur lebih nyenyak, meski angka di dalam buku tersebut tidak berubah sama sekali.'] },
      { chapterNumber: 14, title: 'Selisih Mulai Dibicarakan', paragraphs: ['Di dermaga orang mulai membicarakan selisih muatan gudang yang tidak masuk akal, dan beberapa menebak pengurusnya ceroboh. Sari mendengar tebakan itu dari kuli yang sedang beristirahat. Ia melanjutkan langkah menuju kantor tanpa membenarkan atau menyangkal. Angka sebenarnya tetap tersembunyi dalam rongga lantai kamar, terpisah dari seluruh percakapan di dermaga.'] },
      { chapterNumber: 15, title: 'Hampir Menyerahkan Buku', paragraphs: ['Ketika Bu Hasnah ditahan upahnya, Sari mengeluarkan buku itu dari bawah papan dan membawanya sampai ke pintu gudang. Ia berdiri lama memegang sampulnya. Petugas lewat dan menyapa, lalu Sari menyembunyikan buku di balik kain. Ia pulang membawa kembali catatan yang tidak pernah sampai ke tangan siapa pun.'] },
      { chapterNumber: 16, title: 'Kunci Laci Dipinjam', paragraphs: ['Pemeriksa meminta kunci seluruh laci kantor untuk mencocokkan berkas, dan Sari menyerahkan miliknya tanpa ragu sebab tidak ada apa pun di sana. Ia berdiri menunggu sampai laci ditutup kembali. Perasaan aman itu datang cepat dan penuh. Di rumah, papan lantai kamarnya tetap menyimpan satu-satunya catatan yang benar.'] },
      { chapterNumber: 17, title: 'Upah Ditahan Dua Pekan', paragraphs: ['Kas pelabuhan membekukan bayaran kerja gudang selama empat belas hari sampai selisih dijelaskan, sehingga Bu Hasnah mulai meminjam beras kepada tetangga. Sari mengantar setengah karung tanpa berkata dari mana asalnya. Perempuan itu menerimanya dengan malu. Bantuan tersebut terasa cukup baginya, dan buku pribadinya tetap berada di tempat semula.'] },
      { chapterNumber: 18, title: 'Uweng Menyebut Jalan Keluar', paragraphs: ['Pak Uweng berkata perkara gudang akan selesai bila ada satu catatan tandingan yang memuat angka timbangan asli. Ia mengatakannya sambil membersihkan jarum timbangan, tanpa menatap siapa pun. Sari menjawab bahwa catatan seperti itu tidak mudah dipercaya orang kantor. Juru timbang tersebut mengangguk dan tidak melanjutkan pembicaraan.'] },
      { chapterNumber: 19, title: 'Angka Disalin Diam-diam', paragraphs: ['Sari menyalin tiga baris dari buku pribadinya ke kertas kecil, membacanya sekali, lalu merobeknya menjadi potongan halus di atas tungku. Ia berkata kepada dirinya bahwa waktunya belum tepat. Abu kertas itu tertiup ke lantai dapur. Papan lantai kamarnya ditekan kembali sampai rapat sebelum ia berangkat kerja.'] },
      { chapterNumber: 20, title: 'Berita Acara Ditandatangani', paragraphs: ['Dengan tangan gemetar, Bu Hasnah membubuhkan nama pada berita acara kelalaian di ruang kantor. Sari berada di koridor sambil mendekap tas kerjanya. Ketika perempuan itu keluar, mereka berjalan pulang bersama membicarakan harga ikan. Tidak satu pun dari keduanya menyebut angka gudang, dan tas Sari tetap tertutup rapat sepanjang jalan.'] },
      { chapterNumber: 22, title: 'Papan Lantai Ditutup Lagi', paragraphs: ['Pada hari pemeriksaan, Sari kembali memasukkan buku pribadinya ke bawah papan lantai dan menekan paku yang longgar. Bu Hasnah kehilangan upah bulan itu tanpa pembelaan. Sari membawakan kopi ke gudang dan tidak menyebut catatannya. Ia menjaga posisi yang persis sama seperti ketika buku pertama kali disembunyikan.'] },
    ], justification: 'The ledger leaves its hiding place briefly in Bab 15 but is re-hidden in Bab 22 while Bu Hasnah again pays, so nothing in Sari changes.' },
    { chapters: [
      { chapterNumber: 9, title: 'Lewat Sisi Seberang', paragraphs: ['Sari berjalan di sisi seberang jalan setiap kali melewati warung dermaga agar tidak terlihat dekat dengan pemiliknya. Ia membeli nasi bungkus di kios gerbang. Kebiasaan tersebut membuat pengawas menganggapnya pegawai yang tenang. Ia menikmati nama baik yang murah itu tanpa mempertanyakannya.'] },
      { chapterNumber: 13, title: 'Kios Gerbang Menaikkan Harga', paragraphs: ['Kios dekat gerbang menaikkan harga nasi bungkus karena pembelinya bertambah sejak orang menjauhi warung dermaga. Sari tetap membeli di sana dan membayar selisihnya tanpa mengeluh. Ia menghitung bahwa harga itu masih lebih murah daripada dilihat pengawas sedang duduk di tempat yang salah. Camar mematuk sisa nasi di dekat kakinya.'] },
      { chapterNumber: 14, title: 'Pengawas Mencatat Pengunjung', paragraphs: ['Seorang pengawas duduk di ujung jalan mencatat siapa saja yang masuk ke warung dermaga sepanjang siang. Sari melihat buku catatan itu terbuka di pangkuannya ketika lewat. Ia melangkah lebih cepat dan tidak menoleh. Namanya tidak muncul di halaman mana pun hari itu, dan hal tersebut membuatnya merasa telah mengambil keputusan yang benar.'] },
      { chapterNumber: 15, title: 'Menyapa dari Jauh', paragraphs: ['Ketika Nyi Ratih dipanggil kantor izin, Sari mengangkat tangan menyapa dari seberang jalan dan berkata dalam hati ia akan mampir esok. Ia membeli nasi di kios yang sama. Esok harinya bongkaran padat dan warung penuh petugas. Sapaan jauh itu menjadi satu-satunya hal yang ia berikan.'] },
      { chapterNumber: 16, title: 'Ratih Meminta Keterangan', paragraphs: ['Nyi Ratih menghampirinya di jalan dan meminta satu keterangan tertulis bahwa warungnya dipakai kuli untuk makan, sebab kantor hanya menerima kertas. Sari menjawab bahwa keterangan dari juru catat justru bisa memperberat perkara. Perempuan itu diam sebentar lalu berterima kasih. Keduanya berpisah di simpang tanpa ada yang menyinggung hal tersebut lagi.'] },
      { chapterNumber: 17, title: 'Kuli Menolak Bersaksi', paragraphs: ['Dua kuli bongkar yang setiap malam makan di warung menolak dimintai keterangan karena takut kehilangan giliran angkut. Mereka mengatakannya sambil menghindari tatapan Nyi Ratih. Sari mendengar dari kejauhan dan merasa penolakannya sendiri tidak berbeda dari mereka. Pikiran itu datang sebentar lalu hilang ketika kapal berikutnya merapat.'] },
      { chapterNumber: 18, title: 'Kertas Kosong Disiapkan', paragraphs: ['Sari mengambil selembar kertas bersih dari lemari kantor dan menuliskan tanggal di sudut atasnya. Ia memandangi ruang kosong di bawahnya selama beberapa saat. Lalu petugas memanggilnya untuk memeriksa bongkaran, dan kertas itu ia selipkan di antara berkas lain. Kertas tersebut tidak pernah ia keluarkan kembali sampai pekan berakhir.'] },
      { chapterNumber: 19, title: 'Warung Diberi Batas Waktu', paragraphs: ['Kantor memberi batas waktu tujuh hari bagi pemilik warung untuk melengkapi bukti pemakaian tempat. Pengumuman itu dibaca keras oleh petugas di depan pos jaga. Sari berdiri di barisan belakang sambil memeluk map kerjanya. Ia menghitung hari dalam hati sepanjang perjalanan pulang, lalu berhenti menghitung ketika sampai di pintu rumah.'] },
      { chapterNumber: 20, title: 'Hari Terakhir Berlalu', paragraphs: ['Pada hari ketujuh, Nyi Ratih menunggu di depan warung sampai lewat magrib tanpa seorang pun datang membawa kertas. Sari melintas dari sisi seberang dengan langkah biasa. Lampu warung dimatikan lebih awal malam itu. Ia sampai di rumah tepat waktu, makan seperti biasa, dan namanya masih bersih di daftar mana pun.'] },
      { chapterNumber: 22, title: 'Kursi Warung Tetap Kosong', paragraphs: ['Pada hari pemeriksaan izin, Sari melintas lagi di sisi seberang sambil menunduk membaca berkas. Nyi Ratih berdiri sendirian menghadapi dua petugas. Tidak ada keterangan yang ditulis dan tidak ada tanda tangan yang diberikan. Sari pulang dengan nama baiknya utuh seperti pada hari pertama ia memilih jalan seberang.'] },
    ], justification: 'A wave from across the street replaces action, and Bab 22 repeats the same avoidance while Nyi Ratih stands alone.' },
    { chapters: [
      { chapterNumber: 9, title: 'Peti Dikembalikan Cepat', paragraphs: ['Sari mengembalikan peti bercap meragukan ke kapal tanpa menulis alasan sebenarnya, sebab berkas penolakan yang pendek tidak pernah menimbulkan pertanyaan. Kuli bongkar memuji kecepatan kerjanya. Meja kerjanya tetap rapi sampai petang. Persoalan cap itu berpindah menjauh bersama kapal yang berlayar sore.'] },
      { chapterNumber: 13, title: 'Berkas Penolakan Pendek', paragraphs: ['Sari menulis penolakan sepanjang satu baris untuk peti yang capnya tidak wajar, lalu menyerahkan berkas itu kepada kuli tanpa penjelasan tambahan. Ia sudah hafal susunan kalimatnya sejak musim pertama bekerja. Kapal membawa peti tersebut menjauh sebelum petang. Mejanya kembali lapang, dan tidak ada perkara yang perlu ia bawa pulang.'] },
      { chapterNumber: 14, title: 'Gudang Meminta Catatan', paragraphs: ['Kepala gudang meminta salinan alasan penolakan agar ruang penyimpanan tidak dituduh menerima muatan bermasalah. Sari menjawab bahwa penolakan singkat justru mempercepat urusan semua orang. Lelaki itu menerima jawabannya sambil menandai papan jadwal. Permintaan tersebut tidak diulang, dan Sari melanjutkan cara kerjanya sampai kapal terakhir sandar.'] },
      { chapterNumber: 15, title: 'Menyadari Peti Kembali', paragraphs: ['Sari mengenali nomor lambung pada peti yang dahulu ia tolak, kini masuk melalui petugas lain. Ia berkata kepada Pak Uweng bahwa suatu hari ia akan menahan peti seperti itu di gudang. Juru timbang mengangguk sopan. Sore itu peti tersebut lewat tanpa ditahan siapa pun.'] },
      { chapterNumber: 16, title: 'Tali Rafia Dibeli', paragraphs: ['Sari membeli segulung tali rafia dan menaruhnya di sudut mejanya supaya siap bila suatu hari ada muatan yang perlu disegel. Gulungan itu tetap utuh sampai berdebu. Kuli bongkar sempat memintanya untuk mengikat terpal, dan ia memberikannya begitu saja. Ia membeli gulungan baru pekan berikutnya lalu menaruhnya di tempat yang sama.'] },
      { chapterNumber: 17, title: 'Nomor Lambung Terlihat Lagi', paragraphs: ['Untuk ketiga kalinya musim ini, kapal bernomor lambung yang pernah ia tolak kembali merapat sambil membawa muatan serupa. Sari mengenali nomor tersebut hanya dari ingatan tanpa membuka bukunya. Ia memutuskan tidak menulis apa pun karena catatan lama sudah cukup menjelaskan. Muatan tersebut diterima petugas lain sebelum jam makan siang berakhir.'] },
      { chapterNumber: 18, title: 'Kepala Gudang Menawarkan Segel', paragraphs: ['Kepala gudang menawarkan segel resmi kepada Sari untuk dipakai bila ada muatan yang perlu ditahan sampai pemeriksa datang. Ia menerima segel itu lalu menyimpannya di laci paling bawah bersama kertas bekas. Laci tersebut jarang ia buka. Sampai musim berganti, segel itu belum pernah menempel pada satu peti pun.'] },
      { chapterNumber: 19, title: 'Pemeriksa Menanyakan Riwayat', paragraphs: ['Seorang pemeriksa menanyakan apakah pernah ada muatan yang ditahan di pelabuhan ini. Sari menjawab bahwa muatan bermasalah biasanya dikembalikan langsung ke kapal, dan itu dianggap lebih cepat. Pemeriksa mencatat jawabannya tanpa bertanya lebih jauh. Ia keluar dari ruangan merasa telah menjelaskan sesuatu yang tidak perlu dipertanyakan lagi.'] },
      { chapterNumber: 20, title: 'Kabar Kapal Berikutnya', paragraphs: ['Pak Uweng memberitahunya bahwa kapal bercap ganda akan datang lagi pada bongkaran berikutnya dan mungkin membawa muatan yang lebih besar. Sari mengucapkan terima kasih atas kabar tersebut. Ia membersihkan mejanya lebih awal sore itu, memastikan tidak ada berkas tertinggal. Segel di laci paling bawah tetap berada di bawah tumpukan kertas bekas.'] },
      { chapterNumber: 22, title: 'Dikembalikan Seperti Dulu', paragraphs: ['Peti dengan cap ganda datang lagi, dan Sari menuliskan penolakan pendek lalu memerintahkan kuli menaikkannya kembali ke geladak. Ia tidak menyegel apa pun dan tidak menyebut nomor lambung dalam laporan. Kapal berangkat sebelum magrib. Mejanya tetap rapi, dan wewenangnya tetap utuh seperti sebelum ia menyatakan akan berubah.'] },
    ], justification: 'The stated intention to seal a crate never happens; Bab 22 reproduces the Bab 9 shortcut with Sari’s authority untouched.' },
  ],
  BORDERLINE: [
    { chapters: [
      { chapterNumber: 9, title: 'Nama Ditulis Setengah', paragraphs: ['Sari menuliskan huruf awal namanya lalu meneruskan baris itu memakai nama pengurus gudang di lembar tanggung jawab kiriman garam. Ia menganggap huruf kecil itu sebagai bentuk keberanian yang cukup. Petugas tidak menanyakannya. Berkas berjalan seperti biasa, dan tanggung jawab tetap berhenti pada orang lain.'] },
      { chapterNumber: 13, title: 'Huruf Awal Diperbesar', paragraphs: ['Pada lembar tanggung jawab berikutnya, Sari memperbesar inisial miliknya sebelum meneruskan baris tersebut memakai nama pengurus gudang. Ia memandang hasilnya cukup lama. Petugas loket tidak menanyakan huruf tersebut dan memasukkan lembar itu ke map penerimaan. Nama Bu Hasnah tetap memenuhi bagian terbesar baris tanggung jawab ketika berkas dibawa ke ruang belakang.'] },
      { chapterNumber: 14, title: 'Selisih Mulai Ditanyakan', paragraphs: ['Kantor mulai menanyakan selisih kiriman garam kepada siapa pun yang pernah memegang berkasnya. Bu Hasnah menyebut nama Sari sebagai orang yang menghitung ulang, tetapi petugas hanya mencatat nama penanggung jawab di lembar. Sari mendengar namanya disebut lalu hilang begitu saja. Ia merasa lega dan malu pada waktu yang bersamaan.'] },
      { chapterNumber: 15, title: 'Menemani ke Loket', paragraphs: ['Ketika Bu Hasnah dipanggil karena angka yang meragukan, Sari ikut berdiri di belakang antrean loket dan menyebutkan bahwa ia yang menghitung ulang kiriman itu. Petugas mencatat keterangannya tanpa meminta tanda tangan. Perempuan tua itu tetap yang menandatangani teguran. Sari pulang dengan perasaan lega yang tidak sepenuhnya jujur.'] },
      { chapterNumber: 16, title: 'Menghitung di Depan Petugas', paragraphs: ['Sari meminta izin menghitung ulang kiriman garam di hadapan petugas loket agar angkanya dapat disaksikan langsung. Petugas mengizinkan sambil menunggu berdiri. Hitungan itu selesai dalam dua puluh menit dan hasilnya dicatat sebagai keterangan lisan. Namanya tetap tidak dituliskan di kolom mana pun, dan ia tidak memintanya.'] },
      { chapterNumber: 17, title: 'Damar Menyinggung Wewenang', paragraphs: ['Regent Damar menyebut dalam rapat kecil bahwa juru catat yang terlalu banyak berdiri di loket akan kehilangan waktu untuk pekerjaannya sendiri. Kalimat itu diucapkan tanpa menoleh ke arah Sari. Ia melanjutkan mencatat notulen sampai rapat selesai. Setelahnya ia tetap datang ke loket, hanya pada jam yang lebih sepi.'] },
      { chapterNumber: 18, title: 'Kata Bersama Dicoba', paragraphs: ['Pada lembar latihan buatan sendiri di rumah, Sari menyisipkan kata bersama di antara dua ruang tanda tangan. Ia membacanya keras satu kali untuk mendengar bagaimana bunyinya. Kertas itu ia simpan di dalam tas, bukan di tungku. Ia belum tahu apakah petugas akan menerima bentuk seperti itu pada berkas yang sebenarnya.'] },
      { chapterNumber: 19, title: 'Hasnah Menyetujui Rencana', paragraphs: ['Bu Hasnah menyetujui rencana menandatangani berkas berdua dan berkata itu lebih jujur daripada satu nama yang menanggung semuanya. Keduanya sepakat mencobanya pada berkas terakhir musim ini. Perempuan itu menyimpan lembar tersebut di lemari gudang dan membawa kuncinya pulang. Sari memeriksa sekali lagi bahwa dua ruang tanda tangan tetap kosong berdampingan sebelum pintu dikunci.'] },
      { chapterNumber: 20, title: 'Berkas Terakhir Disiapkan', paragraphs: ['Berkas terakhir musim disiapkan dua hari sebelum penyerahan, lengkap dengan angka hasil hitungan ulang. Sari menyalinnya dengan tinta yang tidak mudah luntur. Ia menyisakan dua ruang kosong berdampingan di bagian bawah, lalu menyerahkan pena pertama kepada Bu Hasnah. Setelah perempuan itu membubuhkan nama, Sari menutup berkas dan menyimpannya tanpa mengisi ruang miliknya.'] },
      { chapterNumber: 22, title: 'Tanda Tangan Berdampingan', paragraphs: ['Pada berkas terakhir, Sari membubuhkan tanda tangannya berdampingan dengan tanda tangan Bu Hasnah dan menulis kata bersama di antara keduanya. Regent Damar menegurnya lisan lalu membiarkan berkas lewat. Sari tidak kehilangan giliran kerja maupun wewenang. Namanya akhirnya muncul, meski beban yang ia tanggung masih dibagi dua.'] },
    ], justification: 'Sari does move from a hidden initial to a co-signature and a verbal reprimand, but the risk stays shared and no concrete loss follows.' },
    { chapters: [
      { chapterNumber: 9, title: 'Latif Dilarang Bertanya', paragraphs: ['Sari melarang Latif menanyakan awak tanpa karcis kepada siapa pun di dermaga. Ia menjelaskan bahwa pertanyaan mudah berubah menjadi laporan bagi orang yang mendengarnya. Adiknya menurut dan kembali menggulung tali basah sampai tangannya perih. Keduanya menjaga jarak dari geladak kapal garam sepanjang sore itu, bahkan ketika derek berhenti lama.'] },
      { chapterNumber: 13, title: 'Tali Basah Digulung Ulang', paragraphs: ['Sepulang kerja, Latif menggulung tali basah di halaman rumah dan bertanya mengapa kakaknya kini sering melihat ke arah geladak kapal garam. Sari menjawab bahwa memandang bukan pelanggaran apa pun. Ia tidak melarang pertanyaan itu seperti dahulu, tetapi juga tidak menjawabnya. Malam berjalan dengan gulungan tali yang bertambah rapi di sudut halaman.'] },
      { chapterNumber: 14, title: 'Ransum Pelayaran Dipersoalkan', paragraphs: ['Kantor izin mempersoalkan jumlah ransum pelayaran terakhir dan meminta keterangan dari siapa pun yang menimbangnya. Pak Uweng menyebut angkanya sesuai catatan tanpa menambah apa-apa. Sari mendengarkan dari balik rak berkas dan tidak melangkah maju. Pertanyaan yang dahulu ia larang kini diucapkan orang lain di ruangan yang sama.'] },
      { chapterNumber: 15, title: 'Bertanya kepada Juru Timbang', paragraphs: ['Sari menemui Pak Uweng di gudang belakang dan menanyakan jatah ransum pelayaran terakhir dengan suara pelan. Juru timbang menjawab singkat lalu meminta pertanyaan itu tidak diulang. Sari tidak meminta salinan halaman. Ia melangkah keluar kebiasaan lamanya sejengkal, tanpa membawa apa pun di tangan.'] },
      { chapterNumber: 16, title: 'Halaman Dibaca Berdiri', paragraphs: ['Sari kembali ke gudang belakang dan membaca halaman ransum sambil berdiri di dekat pintu, tanpa meminta izin menyalinnya. Pak Uweng membiarkan saja selama tidak ada pena yang keluar. Angka-angka itu ia hafalkan sebagian, lalu ia tinggalkan sisanya. Tangannya tetap kosong ketika ia melewati gerbang sore itu.'] },
      { chapterNumber: 17, title: 'Pengawas Menanyakan Kunjungan', paragraphs: ['Seorang pengawas menanyakan mengapa juru catat sering terlihat di gudang belakang pada jam kerja. Sari menjawab bahwa ia mencocokkan berat peti ikan asin. Jawaban itu diterima tanpa catatan tambahan. Ia menyadari kunjungannya sudah terlihat, lalu memilih mengubah jam datangnya alih-alih menghentikannya.'] },
      { chapterNumber: 18, title: 'Latif Menanyakan Upah', paragraphs: ['Latif pulang dengan kabar bahwa seorang awak muda tidak menerima upah selama tiga pelayaran. Sari mendengarkan sampai habis dan tidak menyuruh adiknya berhenti bicara. Ia hanya meminta nama itu tidak diucapkan di dermaga. Percakapan berlanjut sampai lampu teplok mengecil dan keduanya tertidur tanpa kesimpulan.'] },
      { chapterNumber: 19, title: 'Keluhan Umum Disusun', paragraphs: ['Sari menyusun kalimat keluhan yang tidak memuat nama siapa pun di atas kertas bekas pembungkus. Ia membacanya berulang sampai tidak ada satu pun kata yang menunjuk orang tertentu. Bentuk itu ia anggap cukup untuk disampaikan di loket. Kertasnya ia lipat kecil dan ia masukkan ke saku baju kerja.'] },
      { chapterNumber: 20, title: 'Loket Ramai Dipilih', paragraphs: ['Ia sengaja memilih hari ketika loket ramai agar keterangannya didengar banyak orang sekaligus. Latif menawarkan menemani, lalu Sari menyuruhnya bekerja seperti biasa di feri. Antrean panjang mengular sampai ke pintu air pasang. Sari berdiri di barisan dengan kertas lipatan yang mulai lembap di sakunya.'] },
      { chapterNumber: 22, title: 'Menyebut Tanpa Nama', paragraphs: ['Di depan loket, Sari mengatakan ada awak yang bekerja tanpa upah tercatat, tetapi tidak menyebutkan nama siapa pun ketika petugas mendesak. Ia bertahan berdiri sampai keterangannya dicatat sebagai keluhan umum. Latif tetap memperoleh giliran feri. Keberaniannya nyata, namun harganya masih ringan bagi keluarga mereka.'] },
    ], justification: 'She does speak publicly in Bab 22, breaking the Bab 9 rule, yet withholds names and pays no measurable price.' },
    { chapters: [
      { chapterNumber: 9, title: 'Menghindari Kursi Warung', paragraphs: ['Sari tidak pernah duduk di warung dermaga dan memilih makan berdiri di dekat gerbang. Ia menganggap kursi itu tempat orang berbicara terlalu banyak. Nyi Ratih menyapanya sekali, lalu Sari menjawab sambil berjalan. Kebiasaan tersebut menjaga namanya jauh dari daftar mana pun.'] },
      { chapterNumber: 13, title: 'Berdiri Dekat Gerbang', paragraphs: ['Sari makan nasi bungkus sambil berdiri di dekat gerbang, memandang atap warung dermaga dari kejauhan. Seorang kuli menawarkan kursi kosong di sana, lalu ia menolak dengan alasan berkas belum selesai. Bungkus daun ia buang ke tong seng. Jarak yang ia jaga bertahun-tahun terasa sedikit lebih berat dari biasanya.'] },
      { chapterNumber: 14, title: 'Izin Warung Diperiksa', paragraphs: ['Kantor izin mengumumkan pemeriksaan tempat makan di sepanjang dermaga, dimulai dari yang paling dekat dengan pintu air. Nyi Ratih menempelkan kertas izin lamanya di tiang depan. Sari membaca kertas itu dari seberang jalan tanpa berhenti berjalan. Ia menghitung sendiri berapa hari tersisa sebelum petugas sampai ke sana.'] },
      { chapterNumber: 15, title: 'Menitipkan Rantang', paragraphs: ['Ketika izin warung mulai dipersoalkan, Sari menitipkan rantang berisi makanan melalui kuli bongkar tanpa menampakkan diri di depan pintu. Nyi Ratih menerimanya lalu menanyakan siapa pengirim rantang bertutup seng itu. Kuli tersebut mengangkat bahu dan menjawab tidak tahu. Bantuan itu sampai, tetapi tidak ada nama yang menempel padanya.'] },
      { chapterNumber: 16, title: 'Rantang Dikembalikan Kosong', paragraphs: ['Kuli bongkar mengembalikan rantang bertutup seng itu dalam keadaan kosong dan bersih, disertai pesan bahwa pemiliknya ingin tahu siapa pengirimnya. Sari menerima rantang tersebut lalu menyimpannya di bawah meja kerja. Ia tidak menitipkan jawaban apa pun. Pesan itu ia bawa pulang tanpa memutuskan bagaimana harus menanggapinya.'] },
      { chapterNumber: 17, title: 'Kabar Pemeriksaan Menyebar', paragraphs: ['Kabar tentang urutan pemeriksaan menyebar di antara pemilik kios sepanjang jalan dermaga. Beberapa memindahkan meja ke dalam agar terlihat lebih kecil. Sari mendengar semuanya dari antrean loket sambil memegang berkas bongkaran. Ia tidak menyampaikan satu pun kabar itu kepada perempuan yang paling membutuhkannya.'] },
      { chapterNumber: 18, title: 'Bertanya Lewat Kuli', paragraphs: ['Sari menitipkan pertanyaan tentang tanggal pemeriksaan melalui kuli yang sama, masih tanpa menyebutkan siapa yang bertanya. Jawabannya datang esok pagi berupa dua kata dan satu tanggal. Ia menuliskannya di sudut buku muatan. Dengan cara tersebut, identitasnya tetap tidak pernah muncul dalam percakapan sepanjang dermaga.'] },
      { chapterNumber: 19, title: 'Jam Sepi Dihitung', paragraphs: ['Ia memperhatikan kapan petugas terakhir meninggalkan pos jaga dan mencatat jamnya di kepala selama tiga hari berturut-turut. Selalu sekitar pukul tujuh, setelah lampu suar dinyalakan. Sari menyadari ada waktu ketika duduk di warung tidak akan terlihat siapa pun. Ia menyimpan pengetahuan itu untuk dirinya sendiri.'] },
      { chapterNumber: 20, title: 'Berkas Diselesaikan Awal', paragraphs: ['Sari menyelesaikan berkas bongkaran lebih awal dari biasanya agar tidak ada alasan menahannya di meja sampai malam. Rekan kerjanya menanyakan mengapa ia terburu-buru. Ia menjawab ingin pulang lebih cepat. Rantang bertutup seng itu ia bawa keluar dari kolong meja dan ia masukkan ke dalam tas anyaman.'] },
      { chapterNumber: 22, title: 'Duduk Ketika Sepi', paragraphs: ['Sari akhirnya duduk di warung itu, memilih waktu ketika dermaga sepi dan petugas sudah pulang. Ia menanyakan kabar izin dan berjanji akan membantu bila diminta. Tidak ada keterangan tertulis yang ia tinggalkan. Kehadirannya sungguh berubah, meski dipilih pada jam yang tidak menimbulkan risiko.'] },
    ], justification: 'Sari finally occupies the seat she avoided, but chooses an empty hour and leaves no written statement, so the cost stays thin.' },
  ],
}
